function dropStudents(ids) {
  const L = inList(ids);
  for (const t of ['results', 'student_phones', 'phone_hints', 'certificates', 'ex_answers', 'notes', 'iresults']) run(`DELETE FROM ${t} WHERE student_id IN (${L})`, ...ids);
  run(`DELETE FROM students WHERE id IN (${L})`, ...ids);
}
