    toTrash(u, 'probs', rows[0].id, `${rows.length} ta misol`, `${rows[0].grade}-sinf · ${tp.slice(0, 2).join(', ')}${tp.length > 2 ? '…' : ''}`, null, { ids: rows.map(r => r.id) });
